62bb-c535-41ad-9edf-72b3f9da71ed","url":"https://youtu.be/V7p_DmkYLZw?si=huL-RsHxW49BnUii"},{"id":"59d64b36-3918-469b-bd7f-2354638a4cbd","url":"https://youtu.be/7CIM4N4KWHc?si=RU79JpuiwdZU-JkV"},{"id":"54c33aa2-9809-4e82-9c24-cf34449f7833","url":"https://youtu.be/-WR3FczzQ2E?si=xUvChuUNqsYGwthi"},{"id":"5c0a8f4c-5ff9-4123-a539-dc3db9b780e0","url":"https://youtu.be/yRX7bGVx-ZE?si=pkysskzihx4lGsee"},{"id":"039b9bcc-d329-4462-a808-e06688f53a41","url":"https://youtu.be/1OGHbH17u9A?si=hF_Cutk8JzHTCgtC"}]'::jsonb;
BEGIN
  SELECT id INTO v_ws_id FROM public.workspaces WHERE name = 'Drbahaa Coaching';
  IF v_ws_id IS NULL THEN
    RAISE EXCEPTION 'Drbahaa Coaching workspace not found';
  END IF;
  IF (SELECT count(*) FROM public.workspaces WHERE name = 'Drbahaa Coaching') <> 1 THEN
    RAISE EXCEPTION 'Multiple workspaces named Drbahaa Coaching';
  END IF;

  v_cnt := (SELECT count(*) FROM public.exercises WHERE workspace_id = v_ws_id AND NOT is_archived);
  IF v_cnt <> 224 THEN
    RAISE EXCEPTION 'Drbahaa active exercise count is % (expected 224); aborting', v_cnt;
  END IF;

  FOR v_rec IN SELECT id, url FROM jsonb_to_recordset(v_urls) AS t(id uuid, url text) LOOP
    UPDATE public.exercises
       SET video_url = nullif(v_rec.url, ''),
           updated_at = now()
     WHERE id = v_rec.id
       AND workspace_id = v_ws_id;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'exercise % not found under Drbahaa workspace', v_rec.id;
    END IF;
  END LOOP;

  RAISE NOTICE 'Drbahaa video links restored for % rows', (SELECT count(*) FROM public.exercises WHERE workspace_id = v_ws_id AND NOT is_archived AND COALESCE(video_url,'') <> '');
END;
$vid$;
